{
  "items": [
    {
      "title": "The Berlin Pulse – German Foreign Policy 2020",
      "url_or_doi": "https://search.gesis.org/research_data/ZA8988?lang=en",
      "justification": "A survey dataset documenting German public opinion on foreign policy in 2020. Topics include Germany's role in international crises, relations with the United States and China, transatlantic cooperation, perceptions of democracy in other countries, and international security challenges. Particularly relevant for studying German attitudes toward international politics and organisations at the beginning of the 2020s."
    },
    {
      "title": "The Berlin Pulse – German Foreign Policy 2021",
      "url_or_doi": "https://b2find.eudat.eu/dataset/c594ad73-f0a3-5130-a6dc-768eb1cefa18",
      "justification": "Survey data examining German foreign policy preferences in 2021. Covers Germany's relationships with the EU, NATO, United States, Russia, and China, as well as international climate cooperation, military deployments, migration, and global security. Useful for analysing public perceptions of international organisations and Germany's role in multilateral diplomacy."
    },
    {
      "title": "Germany's Role in the World – April 2024",
      "url_or_doi": "https://b2find.eudat.eu/dataset/edc54061-8f0e-5b25-96a6-a28af51095f9",
      "justification": "A 2024 public opinion dataset examining Germany's international influence, global reputation, foreign policy priorities, and involvement in international conflicts. Includes attitudes toward the Russia-Ukraine war, the Israel-Gaza conflict, human rights, and Germany's international responsibilities. Especially useful for researching contemporary German foreign policy and public expectations of international engagement."
    },
    {
      "title": "German Bundestag Open Data",
      "url_or_doi": "https://www.bundestag.de/services/opendata/",
      "justification": "Official open data provided by Germany's federal parliament, including parliamentary documents, proceedings, and information about legislators. Materials from the 2020s can be used to investigate parliamentary debates and legislative activity concerning international relations, European integration, NATO, foreign aid, international treaties, and Germany's participation in international organisations. Particularly valuable for political text analysis and institutional research."
    },
    {
      "title": "OECD Development Finance Statistics – Data on Flows to Developing Countries",
      "url_or_doi": "https://www.oecd.org/en/data/datasets/development-finance-statistics-data-on-flows-to-developing-countries.html",
      "justification": "Official OECD dataset documenting international development finance and foreign assistance provided by donor countries, including Germany. Contains information about official development assistance, recipient countries, financing instruments, and development sectors. Data for the 2020s can support research on German development diplomacy, international cooperation, and engagement with multilateral development organisations."
    },
    {
      "title": "UNHCR Refugee Data Finder",
      "url_or_doi": "https://refugeedata.unhcr.org/en/data-finder/",
      "justification": "International dataset maintained by the United Nations High Commissioner for Refugees containing statistics on refugees, asylum seekers, and other displaced populations. Germany-specific observations from the 2020s can be used to analyse international migration, refugee protection, responses to the war in Ukraine, and Germany's relationship with international humanitarian institutions."
    },
    {
      "title": "UNHCR Refugee Data Portal",
      "url_or_doi": "https://refugeedata.unhcr.org/en/documentation/start-here/about/",
      "justification": "UNHCR's data portal provides access to international displacement statistics and related datasets. Researchers can investigate Germany's position as a refugee-hosting country during the 2020s and compare its migration patterns with those of other European countries. Particularly relevant to the study of international organisations, humanitarian governance, and cross-border political cooperation."
    },
    {
      "title": "Pollux Political Corpora (PoliCorp)",
      "url_or_doi": "https://policorp.pollux-fid.de/about",
      "justification": "A political text corpus incorporating parliamentary speeches and related political materials from Germany. Its coverage includes parliamentary contributions during the 2020s, making it useful for analysing political discourse surrounding international organisations, European integration, foreign relations, and security policy. Researchers can apply computational text analysis to identify changes in political positions and debates."
    },
    {
      "title": "German Comparative Agendas Project",
      "url_or_doi": "https://www.gpa.uni-konstanz.de/",
      "justification": "A research project providing systematically organised information on German political agendas and policy priorities. Its parliamentary datasets can support investigation of international affairs, European policy, defence, and foreign relations. Relevant for studying the prominence of international political issues in German policymaking and comparing foreign policy attention across different periods, including the 2020s where covered."
    },
    {
      "title": "Object-Centric and Traditional Event Data of the German Bundestag",
      "url_or_doi": "https://datasetcatalog.nlm.nih.gov/dataset?q=0002098647",
      "justification": "A research dataset derived from the German Bundestag's parliamentary information system. It structures parliamentary documents, legislative processes, and political activities into event-oriented data. Relevant for investigating legislative decision-making, international policy debates, and the institutional handling of foreign affairs. Researchers should check the dataset's temporal coverage before restricting their analysis to the 2020s."
    }
  ]
}
